// Copies docs/methodology.md (the single source) into src/content/methodology.ts so the /methodology page does not
// depend on files outside web/ at runtime. Runs before every build (npm "prebuild"); the generated file is committed,
// so a build that cannot see ../docs keeps the last copy.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";

const src = new URL("../../docs/methodology.md", import.meta.url);
const out = new URL("../src/content/methodology.ts", import.meta.url);
if (!existsSync(src)) {
  console.log("gen-methodology: ../docs/methodology.md not found, keeping src/content/methodology.ts");
} else {
  mkdirSync(new URL("../src/content/", import.meta.url), { recursive: true });
  const md = readFileSync(src, "utf8").replace(/\r\n/g, "\n");
  writeFileSync(out, `// Generated by scripts/gen-methodology.mjs from docs/methodology.md. Do not edit here.\nexport const METHODOLOGY = ${JSON.stringify(md)};\n`);
  console.log(`gen-methodology: ${md.length} chars → src/content/methodology.ts`);
}
